static Project Single(){var p=new Project();p.Source.LineVoltage=400;var b=new Board{Id="A",Voltage=400};b.Circuits.Add(new Circuit{Id="C",Phases=PhaseMode.Trifasico,PhaseLabel="ABC",Voltage=400,PowerKw=1});p.Boards.Add(b);var c=b.Circuits[0];p.FaultExtremes=new FaultExtremeProfile{LineVoltageV=400,FrequencyHz=p.Frequency,BoundsReference="Limites sintéticos de teste",Coverage="Dois estados QA completos; sem máquinas/conversores adicionais"};var hi=p.FaultExtremes.Maximum;hi.VoltageFactor=1.1;hi.Reference="MáximoQA";hi.DataVersion="v1";hi.Conditions="Rede forte e cabos20C";hi.Sources.Add(Source("S1","A",.01,.03,.02,.04));hi.Branches.Add(Branch(p,c,.02,.005,.025,.007));var lo=hi.Copy();lo.VoltageFactor=.95;lo.Reference="MínimoQA";lo.Conditions="Rede fraca e ramo quente";lo.Sources[0].R1Ohm=.02;lo.Sources[0].X1Ohm=.05;lo.Sources[0].R2Ohm=.03;lo.Sources[0].X2Ohm=.06;lo.Branches[0].R1Ohm=.03;lo.Branches[0].R2Ohm=.04;lo.Branches[0].ConductorTemperatureC=90;p.FaultExtremes.Minimum=lo;return p;}
